style.css:
@-moz-document domain("wattpad.com") {
/* Base styles */
  html, body {
    background-color: #1b1a29 !important;
    color: #fce4ec !important;
    font-family: 'Quicksand', 'Comic Neue', cursive !important;
  }

  /* Hide original Wattpad logos & names */
  header a[href="/"],
  header svg,
  header img[alt*="Wattpad"],
  .Branding__logo,
  .ExploreHeader__logo,
  .Branding__container,
  footer img[alt*="Wattpad"] {
    display: none !important;
  }

  /* Header and nav styling */
  header, nav, .NavigationBar__container {
    background-color: #2c2b3c !important;
    border-bottom: 2px solid #ffb6c1 !important;
    position: relative;
  }

  /* Add a jellyfish image in place of the logo */
  header::before {
    content: "";
    display: block;
    position: absolute;
    top: 10px;
    left: 20px;
    width: 40px;
    height: 40px;
    background-image: url('https://upload.wikimedia.org/wikipedia/commons/6/6a/Jelly_cc11.png'); /* transparent PNG jellyfish */
    background-size: contain;
    background-repeat: no-repeat;
    opacity: 0.9;
    animation: floatJelly 6s ease-in-out infinite;
    z-index: 1000;
  }

  @keyframes floatJelly {
    0% { transform: translateY(0); }
    50% { transform: translateY(-6px); }
    100% { transform: translateY(0); }
  }

  /* Story and content boxes */
  .story-body, .panel, .panel-content, .reading-container, .story-text {
    background-color: #2f2d45 !important;
    color: #ffe0f0 !important;
    border-radius: 10px !important;
    padding: 14px !important;
    box-shadow: 0 0 12px #ffbde9;
  }

  /* Headings */
  h1, h2, h3, h4, h5, h6 {
    color: #ffc8dd !important;
  }

  /* Links and buttons */
  a, button {
    color: #ff9ecb !important;
    text-shadow: 0 0 8px #ffb6c1;
    transition: all 0.3s ease;
  }

  a:hover, button:hover {
    color: #ffdbef !important;
    text-shadow: 0 0 12px #ffe0f0;
    text-decoration: underline !important;
  }

  /* Custom scrollbar */
  ::-webkit-scrollbar {
    width: 10px;
  }

  ::-webkit-scrollbar-thumb {
    background: #ff9ecb;
    border-radius: 10px;
  }

  ::-webkit-scrollbar-track {
    background: #1b1a29;
  }

  /* Footer */
  footer, .Footer__container {
    background-color: #1b1a29 !important;
    color: #fce4ec !important;
  }

  /* Remove ads or banners */
  .Ads__container,
  .PremiumUpsell,
  .WattpadPremiumBanner {
    display: none !important;
  }

  /* Soft glowing background accent */
  body::before {
    content: "";
    position: fixed;
    top: 20%;
    left: 10%;
    width: 300px;
    height: 300px;
    background: radial-gradient(circle at center, rgba(255,182,193,0.2), transparent);
    filter: blur(80px);
    z-index: -1;
    animation: floatGlow 8s ease-in-out infinite;
  }

  @keyframes floatGlow {
    0% { transform: translateY(0); opacity: 0.6; }
    50% { transform: translateY(-20px); opacity: 1; }
    100% { transform: translateY(0); opacity: 0.6; }
  }
}
